import { useTranslation } from 'react-i18next';

import './i18n';
import LanguageSwitcher from './LanguageSwitcher';

export default function App() {
  const { t } = useTranslation();
  const count = 3;
  const userName = 'Alex';

  return (
    <main>
      <nav>
        <a href="/">{t('nav.dashboard')}</a>
        <a href="/tasks">{t('nav.tasks')}</a>
      </nav>
      <LanguageSwitcher />
      <h1>{t('home.greeting', { name: userName })}</h1>
      <p>{t('home.tasksDue', { count })}</p>
      <button>{t('home.addTask')}</button>
      <label>
        <input type="checkbox" /> {t('home.emailOptIn')}
      </label>
    </main>
  );
}

import { useTranslation } from 'react-i18next';
import { supportedLanguages } from './i18n';

// Endonyms: every language is listed in its own language, so someone who lands
// on a locale they can't read can still find their way out. These are never
// translated, so they live in code rather than in the translation files.
const LANGUAGE_NAMES = {
  en: 'English',
  es: 'Español',
  fr: 'Français',
};

export default function LanguageSwitcher() {
  const { t, i18n } = useTranslation();

  return (
    <label>
      {t('language.label')}
      <select
        value={i18n.resolvedLanguage}
        onChange={(event) => i18n.changeLanguage(event.target.value)}
      >
        {supportedLanguages.map((lng) => (
          <option key={lng} value={lng}>
            {LANGUAGE_NAMES[lng]}
          </option>
        ))}
      </select>
    </label>
  );
}

import i18n from 'i18next';
import LanguageDetector from 'i18next-browser-languagedetector';
import { initReactI18next } from 'react-i18next';

import en from './locales/en/translation.json';
import es from './locales/es/translation.json';
import fr from './locales/fr/translation.json';

export const supportedLanguages = ['en', 'es', 'fr'];

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: en },
      es: { translation: es },
      fr: { translation: fr },
    },
    supportedLngs: supportedLanguages,
    // Let regional tags resolve to their base language: es-MX -> es.
    nonExplicitSupportedLngs: true,
    fallbackLng: 'en',
    interpolation: {
      // React escapes interpolated values already; escaping here too would
      // mangle names like O'Brien into O&#39;Brien.
      escapeValue: false,
    },
    detection: {
      order: ['localStorage', 'navigator'],
      caches: ['localStorage'],
    },
  });

// Keep the document in sync so screen readers, hyphenation and spellcheck use
// the right language, and so RTL locales flip direction when they're added.
function syncDocumentLanguage(lng) {
  if (typeof document === 'undefined') return;
  document.documentElement.lang = lng;
  document.documentElement.dir = i18n.dir(lng);
}

syncDocumentLanguage(i18n.resolvedLanguage);
i18n.on('languageChanged', syncDocumentLanguage);

export default i18n;

