  "name": "demo",
  "private": true,
  "scripts": {
    "extract": "neokapi-i18n extract",
    "compile": "neokapi-i18n compile i18n --out public/translations",
    "lint:i18n": "oxlint src"
  },
  "dependencies": {
    "react": "^19.0.0"
  },
  "devDependencies": {
    "@neokapi/i18n-react": "^1.2.3",
    "@neokapi/i18n-react-lint": "^0.1.1",
    "oxlint": "^1.42.0"
  }
