#!/usr/bin/env node
/**
 * Temporary shim: @neokapi/i18n-react 1.2.3 emits catalogs with
 * kind "kapi-localization-format" (.klf); the pinned kapi CLI
 * (v1.2.0-rc28) only registers the "kapi-bundle" kind (.kbf.json).
 * The payloads are otherwise identical, so we rewrite the discriminator
 * on the way in and back out.
 *
 * Delete this once the kapi CLI ships KLF support (`kapi formats | grep klf`).
 *
 *   node scripts/klf-bridge.mjs to-kbf   i18n/src/App.klf  build/i18n/App.kbf.json
 *   node scripts/klf-bridge.mjs from-kbf build/i18n/App.kbf.json  i18n/fr/App.klf
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";

const KLF = "kapi-localization-format";
const KBF = "kapi-bundle";
const [dir, input, output] = process.argv.slice(2);

if (!["to-kbf", "from-kbf"].includes(dir) || !input || !output) {
  console.error("usage: klf-bridge.mjs <to-kbf|from-kbf> <input> <output>");
  process.exit(2);
}

const doc = JSON.parse(readFileSync(input, "utf8"));
const [expected, next] = dir === "to-kbf" ? [KLF, KBF] : [KBF, KLF];

if (doc.kind !== expected && doc.kind !== next) {
  console.error(`refusing: ${input} has kind "${doc.kind}", expected "${expected}"`);
  process.exit(1);
}
doc.kind = next;

mkdirSync(dirname(output), { recursive: true });
writeFileSync(output, JSON.stringify(doc, null, 2) + "\n");
console.log(`${input} → ${output} (kind: ${next})`);

