#!/usr/bin/env python3
"""Parse application log files.

Expected line format:
    YYYY-MM-DD HH:MM:SS LEVEL message

Example:
    2026-08-01 12:00:01 WARN slow query 431ms
"""

import argparse
import json
import re
import sys
from dataclasses import dataclass, asdict
from datetime import datetime

LINE_RE = re.compile(
    r"^(?P<timestamp>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+"
    r"(?P<level>[A-Z]+)\s+"
    r"(?P<message>.*)$"
)

TIMESTAMP_FORMAT = "%Y-%m-%d %H:%M:%S"


@dataclass
class Entry:
    source: str
    lineno: int
    timestamp: datetime
    level: str
    message: str

    def to_dict(self):
        d = asdict(self)
        d["timestamp"] = self.timestamp.isoformat(sep=" ")
        return d


def parse_line(line, source, lineno):
    """Return an Entry, or None if the line does not match the log format."""
    match = LINE_RE.match(line.rstrip("\n"))
    if not match:
        return None
    try:
        timestamp = datetime.strptime(match["timestamp"], TIMESTAMP_FORMAT)
    except ValueError:
        return None
    return Entry(
        source=source,
        lineno=lineno,
        timestamp=timestamp,
        level=match["level"],
        message=match["message"].strip(),
    )


def parse_file(path):
    """Yield (Entry | None, raw_line) for every line in the file."""
    with open(path, "r", encoding="utf-8", errors="replace") as handle:
        for lineno, raw in enumerate(handle, start=1):
            if not raw.strip():
                continue
            yield parse_line(raw, path, lineno), raw.rstrip("\n")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__,
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("files", nargs="+", help="log files to parse")
    parser.add_argument("--level", action="append", metavar="LEVEL",
                        help="only show entries at this level (repeatable)")
    parser.add_argument("--contains", metavar="TEXT",
                        help="only show entries whose message contains TEXT")
    parser.add_argument("--since", metavar="'YYYY-MM-DD HH:MM:SS'",
                        help="only show entries at or after this time")
    parser.add_argument("--until", metavar="'YYYY-MM-DD HH:MM:SS'",
                        help="only show entries at or before this time")
    parser.add_argument("--json", action="store_true",
                        help="emit entries as a JSON array instead of text")
    parser.add_argument("--summary", action="store_true",
                        help="print per-level counts and time range instead of entries")
    args = parser.parse_args(argv)

    def parse_bound(value, flag):
        if value is None:
            return None
        try:
            return datetime.strptime(value, TIMESTAMP_FORMAT)
        except ValueError:
            parser.error(f"{flag} must look like 'YYYY-MM-DD HH:MM:SS', got {value!r}")

    since = parse_bound(args.since, "--since")
    until = parse_bound(args.until, "--until")
    levels = {lvl.upper() for lvl in args.level} if args.level else None

    entries = []
    malformed = []
    for path in args.files:
        try:
            lines = list(parse_file(path))
        except OSError as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 2
        for entry, raw in lines:
            if entry is None:
                malformed.append((path, raw))
                continue
            if levels and entry.level not in levels:
                continue
            if args.contains and args.contains not in entry.message:
                continue
            if since and entry.timestamp < since:
                continue
            if until and entry.timestamp > until:
                continue
            entries.append(entry)

    entries.sort(key=lambda e: (e.timestamp, e.source, e.lineno))

    if args.summary:
        counts = {}
        for entry in entries:
            counts[entry.level] = counts.get(entry.level, 0) + 1
        print(f"files:   {len(args.files)}")
        print(f"entries: {len(entries)}")
        if entries:
            print(f"range:   {entries[0].timestamp} .. {entries[-1].timestamp}")
        for level, count in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0])):
            print(f"  {level:<8} {count}")
    elif args.json:
        json.dump([e.to_dict() for e in entries], sys.stdout, indent=2)
        sys.stdout.write("\n")
    else:
        for entry in entries:
            print(f"{entry.timestamp} {entry.level:<5} {entry.message}")

    for path, raw in malformed:
        print(f"warning: unparsed line in {path}: {raw!r}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Parse application logs of the form:

    2026-08-01 12:00:00 INFO started
    2026-08-01 12:00:01 WARN slow query 431ms

Usage:
    ./parse_logs.py app.log                 # one line per entry
    ./parse_logs.py *.log --json            # JSON Lines
    ./parse_logs.py app.log --level WARN    # only WARN and above
    ./parse_logs.py app.log --summary       # counts per level
"""

import argparse
import json
import re
import sys
from dataclasses import dataclass, asdict
from datetime import datetime

LINE_RE = re.compile(
    r"^(?P<ts>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+"
    r"(?P<level>[A-Z]+)\s+"
    r"(?P<message>.*)$"
)

TS_FORMAT = "%Y-%m-%d %H:%M:%S"

# Ordered least to most severe; used by --level to filter.
SEVERITY = {"TRACE": 0, "DEBUG": 1, "INFO": 2, "WARN": 3, "WARNING": 3, "ERROR": 4, "FATAL": 5}


@dataclass
class Entry:
    timestamp: datetime
    level: str
    message: str
    source: str
    lineno: int

    def as_dict(self):
        d = asdict(self)
        d["timestamp"] = self.timestamp.isoformat(sep=" ")
        return d

    def __str__(self):
        return f"{self.timestamp:{TS_FORMAT}} {self.level:<5} {self.message}"


def parse_line(line, source, lineno):
    """Return an Entry, or None if the line does not match the log format."""
    m = LINE_RE.match(line.rstrip("\n"))
    if not m:
        return None
    try:
        ts = datetime.strptime(m["ts"], TS_FORMAT)
    except ValueError:
        return None
    return Entry(ts, m["level"], m["message"].strip(), source, lineno)


def parse_file(path):
    """Yield (Entry, raw_line) pairs; Entry is None for unparseable lines."""
    stream = sys.stdin if path == "-" else open(path, encoding="utf-8", errors="replace")
    name = "<stdin>" if path == "-" else path
    try:
        for lineno, line in enumerate(stream, 1):
            if not line.strip():
                continue
            yield parse_line(line, name, lineno), line.rstrip("\n")
    finally:
        if stream is not sys.stdin:
            stream.close()


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("paths", nargs="+", help="log files to parse ('-' for stdin)")
    ap.add_argument("--level", help="only show entries at this level or more severe")
    ap.add_argument("--json", action="store_true", help="emit JSON Lines instead of text")
    ap.add_argument("--summary", action="store_true", help="print counts per level instead of entries")
    args = ap.parse_args(argv)

    min_severity = 0
    if args.level:
        key = args.level.upper()
        if key not in SEVERITY:
            ap.error(f"unknown level {args.level!r}; known levels: {', '.join(sorted(SEVERITY))}")
        min_severity = SEVERITY[key]

    counts = {}
    malformed = 0

    for path in args.paths:
        try:
            lines = parse_file(path)
            for entry, raw in lines:
                if entry is None:
                    malformed += 1
                    print(f"{path}: skipping unparseable line: {raw!r}", file=sys.stderr)
                    continue
                counts[entry.level] = counts.get(entry.level, 0) + 1
                # Unknown levels sort as most severe so they are never silently dropped.
                if SEVERITY.get(entry.level, max(SEVERITY.values())) < min_severity:
                    continue
                if args.summary:
                    continue
                print(json.dumps(entry.as_dict()) if args.json else entry)
        except OSError as e:
            print(f"error: {e}", file=sys.stderr)
            return 1

    if args.summary:
        if args.json:
            print(json.dumps({"levels": counts, "malformed": malformed}))
        else:
            for level, n in sorted(counts.items(), key=lambda kv: -kv[1]):
                print(f"{level:<8} {n}")
            print(f"{'TOTAL':<8} {sum(counts.values())}")
            if malformed:
                print(f"{'SKIPPED':<8} {malformed}", file=sys.stderr)

    return 0


if __name__ == "__main__":
    sys.exit(main())

